   129→        ensureFinanceOrAdmin(principal);
   130→        if (payment.getProvider() != PaymentProvider.CHAPA) {
   131→            throw new IllegalArgumentException("Verification endpoint only supports Chapa payments");
   132→        }
   133→
   134→        PaymentStatus newStatus = mapExternalStatus(request.status());
   135→        payment.setProviderReference(request.providerReference());
   136→        payment.setStatus(newStatus);
   137→        payment.setVerifiedBy(principal.getId());
   138→        payment.setVerifiedAt(Instant.now());
   139→        payment.setVerificationPayload(Map.of(
   140→                "status", request.status(),
   141→                "message", request.message() == null ? "" : request.message(),
   142→                "verifiedBy", principal.getId()));
