   287→    private void refreshAfterPayment(PaymentRecord payment, String reviewerId) {
   288→        ClearanceRequest clearanceRequest = getRequest(payment.getClearanceRequestId());
   289→        if (payment.getStatus() == PaymentStatus.SUCCESS) {
   290→            clearanceRequest.setStatus(ClearanceRequestStatus.IN_REVIEW);
   291→            moveDepartmentCheckToPendingApproval(payment, reviewerId);
   292→        } else if (payment.getStatus() == PaymentStatus.FAILED) {
   293→            clearanceRequest.setStatus(ClearanceRequestStatus.PAYMENT_PENDING);
   294→        }
   295→        clearanceRequestRepository.save(clearanceRequest);
   296→    }
