   298→    private void moveDepartmentCheckToPendingApproval(PaymentRecord payment, String reviewerId) {
   299→        if (payment.getDepartmentCheckCode() == null) {
   300→            return;
   301→        }
   302→
   303→        ClearanceCheck departmentCheck = clearanceCheckRepository
   304→                .findByClearanceRequestIdAndCheckCode(payment.getClearanceRequestId(), payment.getDepartmentCheckCode())
   305→                .orElseThrow(() -> new IllegalArgumentException("Department check not found"));
   306→
   307→        departmentCheck.setStatus(ClearanceCheckStatus.PAID_PENDING_DEPARTMENT_APPROVAL);
   308→        departmentCheck.setComment(buildFinanceReceiptComment(payment));
   309→        departmentCheck.setReviewedBy(reviewerId);
   310→        departmentCheck.setReviewedAt(Instant.now());
   311→        clearanceCheckRepository.save(departmentCheck);
   312→    }
