   314→    private List<Liability> getLiabilitiesForPayment(ClearanceRequest clearanceRequest, List<String> liabilityIds) {
   315→        List<Liability> liabilities = liabilityRepository.findAllById(liabilityIds);
   316→        if (liabilities.isEmpty() || liabilities.size() != liabilityIds.size()) {
   317→            throw new IllegalArgumentException("One or more liabilities were not found");
   318→        }
   319→        boolean invalid = liabilities.stream().anyMatch(liability ->
   320→                !liability.getClearanceRequestId().equals(clearanceRequest.getId())
   321→                        || !liability.isPaymentRequired()
   322→                        || liability.getStatus() == LiabilityStatus.PAID
   323→                        || liability.getStatus() == LiabilityStatus.CLEARED);
   324→        if (invalid) {
   325→            throw new IllegalArgumentException("Selected liabilities are not eligible for payment");
   326→        }
   327→        return liabilities;
   328→    }
