   330→    private ClearanceCheckCode resolveDepartmentCheckCode(List<Liability> liabilities) {
   331→        HashSet<ClearanceCheckCode> checkCodes = new HashSet<>();
   332→        for (Liability liability : liabilities) {
   333→            checkCodes.add(liability.getDepartmentCheckCode());
   334→        }
   335→        if (checkCodes.size() != 1) {
   336→            throw new IllegalArgumentException("A payment must belong to one department workflow at a time");
   337→        }
   338→        return liabilities.get(0).getDepartmentCheckCode();
   339→    }
