   365→    private PaymentStatus mapExternalStatus(String status) {
   366→        if (status == null) {
   367→            return PaymentStatus.PENDING_VERIFY;
   368→        }
   369→        return switch (status.toUpperCase()) {
   370→            case "SUCCESS", "PAID", "COMPLETED" -> PaymentStatus.SUCCESS;
   371→            case "FAILED", "ERROR" -> PaymentStatus.FAILED;
   372→            case "CANCELLED" -> PaymentStatus.CANCELLED;
   373→            default -> PaymentStatus.PENDING_VERIFY;
   374→        };
   375→    }
