   391→    private String initializeChapaCheckout(PaymentRecord payment, Student student) {
   392→        if (!StringUtils.hasText(chapaProperties.getSecretKey())) {
   393→            return chapaProperties.getCheckoutBaseUrl() + "?tx_ref=" + payment.getTxRef();
   394→        }
   395→        if (!StringUtils.hasText(student.getEmail())) {
   396→            throw new IllegalArgumentException("Student email is required before initiating Chapa payment");
   397→        }
   398→
   399→        Map<String, Object> payload = Map.of(
   400→                "amount", payment.getAmount().toPlainString(),
   401→                "currency", payment.getCurrency(),
   402→                "email", student.getEmail(),
   403→                "first_name", firstNonBlank(student.getFirstName(), student.getStudentId()),
   404→                "last_name", firstNonBlank(student.getLastName(), student.getMiddleName(), "Student"),
   405→                "phone_number", student.getPhone() == null ? "" : student.getPhone(),
   406→                "tx_ref", payment.getTxRef(),
   407→                "callback_url", chapaProperties.getCallbackUrl(),
   408→                "return_url", chapaProperties.getReturnUrl());
   409→
   410→        try {
   411→            JsonNode response = restClient.post()
   412→                    .uri(chapaProperties.getInitializeUrl())
   413→                    .header(HttpHeaders.AUTHORIZATION, "Bearer " + chapaProperties.getSecretKey())
   414→                    .contentType(MediaType.APPLICATION_JSON)
   415→                    .body(payload)
   416→                    .retrieve()
   417→                    .body(JsonNode.class);
   418→
   419→            String checkoutUrl = response == null ? null : response.path("data").path("checkout_url").asText(null);
   420→            if (!StringUtils.hasText(checkoutUrl)) {
   421→                throw new IllegalArgumentException("Chapa did not return a checkout URL");
   422→            }
   423→            return checkoutUrl;
   424→        } catch (Exception ex) {
   425→            throw new IllegalArgumentException("Unable to initialize Chapa payment: " + ex.getMessage(), ex);
   426→        }
   427→    }
