   433→            String message
   434→    ) {
   435→        PaymentRecord payment = paymentRecordRepository.findByTxRef(txRef)
   436→                .orElseThrow(() -> new IllegalArgumentException("Payment not found"));
   437→        if (payment.getProvider() != PaymentProvider.CHAPA) {
   438→            throw new IllegalArgumentException("Payment is not a Chapa payment");
   439→        }
   440→        if (payment.getStatus() == PaymentStatus.SUCCESS) {
   441→            return toResponse(payment);
