   443→
   444→        ChapaVerificationResult verificationResult = verifyWithChapa(txRef, callbackStatus, providerReference, message);
   445→        payment.setProviderReference(verificationResult.providerReference());
   446→        payment.setStatus(verificationResult.status());
   447→        payment.setVerificationPayload(verificationResult.payload());
   448→
   449→        if (verificationResult.status() == PaymentStatus.SUCCESS) {
   450→            payment.setVerifiedAt(Instant.now());
   451→            markPaidLiabilities(payment, null);
   452→        }
   453→
   454→        payment = paymentRecordRepository.save(payment);
   455→        refreshAfterPayment(payment, null);
   456→        return toResponse(payment);
   457→    }
