   334→    private void validateRoleForCheck(UserRole role, ClearanceCheckCode checkCode) {
   335→        if (role == UserRole.SYSTEM_ADMIN) {
   336→            return;
   337→        }
   338→
   339→        boolean allowed = switch (role) {
   340→            case LIBRARIAN -> checkCode == ClearanceCheckCode.LIBRARY;
   341→            case PROCTOR -> checkCode == ClearanceCheckCode.PROCTOR;
   342→            case CAFE_STAFF -> checkCode == ClearanceCheckCode.CAFE;
   343→            case DEPARTMENT_HEAD -> checkCode == ClearanceCheckCode.DEPARTMENT_HEAD;
   344→            case STUDENT_DEAN -> checkCode == ClearanceCheckCode.STUDENT_DEAN;
   345→            default -> false;
   346→        };
   347→
   348→        if (!allowed) {
   349→            throw new AccessDeniedException("Your role cannot manage this clearance check");
   350→        }
   351→    }
