   357→    private void refreshCheckStatusFromLiabilities(String clearanceRequestId, ClearanceCheckCode checkCode, String reviewerId) {
   358→        ClearanceRequest request = getClearanceRequest(clearanceRequestId);
   359→        String studentId = request.getStudentId();
   360→        List<Liability> liabilities = liabilityRepository.findByStudentIdAndDepartmentCheckCode(studentId, checkCode);
   361→        boolean hasOutstandingPayment = liabilities.stream()
   362→                .anyMatch(liability -> liability.isPaymentRequired()
   363→                        && liability.getStatus() != LiabilityStatus.PAID
   364→                        && liability.getStatus() != LiabilityStatus.CLEARED
   365→                        && liability.getStatus() != LiabilityStatus.WAIVED);
   366→        boolean hasOutstandingNonPayment = liabilities.stream()
   367→                .anyMatch(liability -> !liability.isPaymentRequired()
   368→                        && liability.getStatus() != LiabilityStatus.CLEARED
   369→                        && liability.getStatus() != LiabilityStatus.WAIVED);
   370→
   371→        if (hasOutstandingPayment) {
   372→            updateCheckStatus(
   373→                    clearanceRequestId,
   374→                    checkCode,
   375→                    ClearanceCheckStatus.AWAITING_FINANCE,
   376→                    reviewerId,
   377→                    "Outstanding payment must be completed and verified by finance.");
   378→            return;
   379→        }
   380→
   381→        if (!hasOutstandingNonPayment) {
   382→            updateCheckStatus(
   383→                    clearanceRequestId,
   384→                    checkCode,
   385→                    ClearanceCheckStatus.IN_REVIEW,
   386→                    reviewerId,
   387→                    "All recorded issues are resolved. Final departmental approval is required.");
   388→        }
   389→    }
