   395→
   396→        List<Liability> liabilities = liabilityRepository.findByStudentIdAndDepartmentCheckCode(
   397→                check.getStudentId(),
   398→                check.getCheckCode());
   399→
   400→        boolean hasOutstandingPayment = liabilities.stream()
   401→                .anyMatch(liability -> liability.isPaymentRequired()
   402→                        && liability.getStatus() != LiabilityStatus.PAID
   403→                        && liability.getStatus() != LiabilityStatus.CLEARED
   404→                        && liability.getStatus() != LiabilityStatus.WAIVED);
   405→        if (hasOutstandingPayment) {
   406→            throw new IllegalArgumentException("Finance must verify payment before this department can clear the student");
   407→        }
   408→
   409→        boolean hasOutstandingNonPayment = liabilities.stream()
   410→                .anyMatch(liability -> !liability.isPaymentRequired()
   411→                        && liability.getStatus() != LiabilityStatus.CLEARED
   412→                        && liability.getStatus() != LiabilityStatus.WAIVED);
   413→        if (hasOutstandingNonPayment) {
   414→            throw new IllegalArgumentException("Outstanding department issues must be resolved before clearance");
