    24→  useEffect(() => {
    25→    let cancelled = false;
    26→
    27→    async function hydrate() {
    28→      try {
    29→        const savedToken = await storage.getToken();
    30→        if (!savedToken) {
    31→          if (!cancelled) {
    32→            setLoading(false);
    33→          }
    34→          return;
    35→        }
    36→
    37→        const currentUser = await api.getCurrentUser(savedToken);
    38→        if (!cancelled) {
    39→          setToken(savedToken);
    40→          setUser({ ...currentUser, mustChangePassword: false });
    41→          setMustChangePassword(false);
    42→        }
    43→      } catch {
    44→        await storage.clearToken();
    45→        await storage.clearDashboardCache();
    46→        if (!cancelled) {
    47→          setToken(null);
    48→          setUser(null);
    49→          setMustChangePassword(false);
    50→        }
    51→      } finally {
    52→        if (!cancelled) {
    53→          setLoading(false);
    54→        }
    55→      }
    56→    }
    57→
    58→    void hydrate();
    59→
    60→    return () => {
    61→      cancelled = true;
    62→    };
    63→  }, []);
    64→
    65→  const value = useMemo<AuthContextValue>(
    66→    () => ({
    67→      user,
    68→      token,
    69→      loading,
    70→      mustChangePassword,
    71→      async login(username: string, password: string) {
    72→        const response = await api.login(username, password);
    73→        await storage.setToken(response.accessToken);
    74→        setToken(response.accessToken);
    75→        try {
    76→          const currentUser = await api.getCurrentUser(response.accessToken);
    77→          setUser({ ...currentUser, mustChangePassword: response.mustChangePassword });
    78→          setMustChangePassword(response.mustChangePassword);
    79→        } catch (error) {
    80→          await storage.clearToken();
    81→          await storage.clearDashboardCache();
    82→          setToken(null);
    83→          setUser(null);
    84→          setMustChangePassword(false);
    85→          throw error;
    86→        }
    87→      },
