    94→        await storage.clearDashboardCache();
    95→        setToken(null);
    96→        setUser(null);
    97→        setMustChangePassword(false);
    98→      }
    99→    }),
   100→    [loading, mustChangePassword, token, user]
   101→  );
   102→
   103→  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
   104→}
