    10→const API_BASE_URL = process.env.EXPO_PUBLIC_API_BASE_URL ?? "http://localhost:8080/api/v1";
    11→
    12→async function request<T>(path: string, options: RequestInit = {}, token?: string): Promise<T> {
    13→  const response = await fetch(`${API_BASE_URL}${path}`, {
    14→    ...options,
    15→    headers: {
    16→      "Content-Type": "application/json",
    17→      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    18→      ...(options.headers ?? {})
    19→    }
    20→  });
    21→
    22→  if (!response.ok) {
    23→    let message = "Request failed";
    24→    try {
    25→      const errorBody = (await response.json()) as { message?: string };
    26→      message = errorBody.message ?? message;
    27→    } catch {
    28→      message = response.statusText || message;
    29→    }
    30→    throw new Error(message);
    31→  }
    32→
    33→  if (response.status === 204) {
    34→    return undefined as T;
    35→  }
    36→
    37→  return (await response.json()) as T;
    38→}
