          </Text>

          <View style={[styles.card, {
            backgroundColor: isDark ? "rgba(20,22,28,0.9)" : "rgba(255,255,255,0.72)",
            borderColor: isDark ? "rgba(255,255,255,0.06)" : "rgba(0,0,0,0.05)",
