import { Ionicons, MaterialIcons } from "@expo/vector-icons";
import { LinearGradient } from "expo-linear-gradient";
import { useState } from "react";
import { KeyboardAvoidingView, Platform, Pressable, ScrollView, StyleSheet, Text, TextInput, View } from "react-native";
import { api } from "../lib/api";
import { useAuth } from "../modules/auth/AuthContext";
import { useTheme } from "../modules/theme/ThemeContext";

export function ChangePasswordScreen() {
  const { token, completePasswordChange, logout } = useAuth();
  const { tokens, mode } = useTheme();
  const [currentPassword, setCurrentPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  const isDark = mode === "dark";

  async function handleSubmit() {
    if (!token) return;
    if (newPassword !== confirmPassword) {
      setError("New password and confirmation do not match");
      return;
    }
    if (newPassword.length < 8) {
      setError("Password must be at least 8 characters");
      return;
    }

    setSaving(true);
    setError(null);
    try {
      await api.changePassword(token, currentPassword, newPassword);
      setSuccess(true);
      setTimeout(() => completePasswordChange(), 800);
    } catch (requestError) {
      setError(requestError instanceof Error ? requestError.message : "Unable to change password");
    } finally {
      setSaving(false);
    }
  }

  if (success) {
    return (
      <View style={[styles.centered, { backgroundColor: tokens.background }]}>
        <View style={[styles.successCard, {
          backgroundColor: isDark ? tokens.surfaceContainerLow : tokens.surfaceContainerLowest,
          ...tokens.shadowSoft,
        }]}>
          <MaterialIcons name="check-circle" size={48} color={tokens.secondary} />
          <Text style={[styles.successTitle, { color: tokens.onSurface }]}>Password Updated</Text>
          <Text style={[styles.successBody, { color: tokens.onSurfaceVariant }]}>
            Your password has been changed successfully. Taking you back to the app…
          </Text>
        </View>
      </View>
    );
  }

  return (
    <View style={[styles.root, { backgroundColor: tokens.background }]}>
      <LinearGradient colors={[isDark ? tokens.primaryContainer : "#000511", isDark ? "#001e40" : "#006a63"]} start={{ x: 0, y: 0 }} end={{ x: 1, y: 0 }}
        style={[styles.appBar, { paddingTop: Platform.OS === "ios" ? 44 : 0 }]}
      >
        <View style={styles.appBarLeft}>
          <View style={styles.logoCircle}>
            <MaterialIcons name="school" size={20} color="#fff" />
          </View>
          <Text style={styles.appBarTitle}>Secure Access</Text>
        </View>
      </LinearGradient>

      <KeyboardAvoidingView behavior={Platform.OS === "ios" ? "padding" : undefined} style={{ flex: 1 }}>
        <ScrollView contentContainerStyle={styles.scroll}>
          <Text style={[styles.eyebrow, { color: tokens.secondary }]}>First login</Text>
          <Text style={[styles.title, { color: tokens.onSurface }]}>Choose a secure password</Text>
          <Text style={[styles.copy, { color: tokens.onSurfaceVariant }]}>
            Replace the temporary password from the super admin before using the student portal.
          </Text>

          <View style={[styles.card, {
            backgroundColor: isDark ? tokens.surfaceContainerLow : tokens.surfaceContainerLowest,
            borderColor: isDark ? tokens.outlineVariant : "rgba(0,0,0,0.06)",
            ...tokens.shadowSoft,
          }]}>
            <View style={styles.headIcon}>
              <Ionicons name="shield-checkmark" size={28} color={tokens.secondary} />
            </View>

            <Text style={[styles.fieldLabel, { color: tokens.onSurfaceVariant }]}>Current Password</Text>
            <View style={[styles.inputRow, { backgroundColor: tokens.surfaceContainerLowest, borderColor: tokens.outlineVariant }]}>
              <MaterialIcons name="lock" size={20} color={tokens.outline} />
              <TextInput
                style={[styles.input, { color: tokens.onSurface }]}
                value={currentPassword}
                onChangeText={setCurrentPassword}
                secureTextEntry
                placeholder="Current password"
                placeholderTextColor={tokens.onSurfaceVariant}
              />
            </View>

            <Text style={[styles.fieldLabel, { color: tokens.onSurfaceVariant }]}>New Password</Text>
            <View style={[styles.inputRow, { backgroundColor: tokens.surfaceContainerLowest, borderColor: tokens.outlineVariant }]}>
              <MaterialIcons name="vpn-key" size={20} color={tokens.outline} />
              <TextInput
                style={[styles.input, { color: tokens.onSurface }]}
                value={newPassword}
                onChangeText={setNewPassword}
                secureTextEntry
                placeholder="At least 8 characters"
                placeholderTextColor={tokens.onSurfaceVariant}
              />
            </View>

            <Text style={[styles.fieldLabel, { color: tokens.onSurfaceVariant }]}>Confirm New Password</Text>
            <View style={[styles.inputRow, { backgroundColor: tokens.surfaceContainerLowest, borderColor: tokens.outlineVariant }]}>
              <MaterialIcons name="vpn-key" size={20} color={tokens.outline} />
              <TextInput
                style={[styles.input, { color: tokens.onSurface }]}
                value={confirmPassword}
                onChangeText={setConfirmPassword}
                secureTextEntry
                placeholder="Confirm new password"
                placeholderTextColor={tokens.onSurfaceVariant}
              />
            </View>

            {error ? (
              <View style={[styles.errorBox, { backgroundColor: tokens.errorContainer }]}>
                <MaterialIcons name="error-outline" size={16} color={tokens.onErrorContainer} />
                <Text style={[styles.errorText, { color: tokens.onErrorContainer }]}>{error}</Text>
              </View>
            ) : null}

            <Pressable
              style={({ pressed }) => [styles.primaryBtn, {
                backgroundColor: tokens.secondary,
                shadowColor: isDark ? "#000" : "#006a63",
                opacity: pressed || saving ? 0.85 : 1,
              }]}
              onPress={() => void handleSubmit()}
              disabled={saving}
            >
              <Text style={styles.primaryBtnText}>{saving ? "Saving…" : "Save & Continue"}</Text>
              <MaterialIcons name="arrow-forward" size={20} color="#fff" />
            </Pressable>
            <Pressable
              style={({ pressed }) => [styles.secondaryBtn, {
                borderColor: tokens.outlineVariant,
                backgroundColor: isDark ? "transparent" : "transparent",
                opacity: pressed ? 0.7 : 1,
              }]}
              onPress={() => void logout()}
            >
              <Text style={[styles.secondaryBtnText, { color: tokens.onSurface }]}>Sign out</Text>
            </Pressable>
          </View>
        </ScrollView>
      </KeyboardAvoidingView>
    </View>
  );
}

const styles = StyleSheet.create({
  root: { flex: 1 },
  appBar: {
    height: Platform.OS === "ios" ? 88 : 64,
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "space-between",
    paddingHorizontal: 20,
  },
  appBarLeft: { flexDirection: "row", alignItems: "center", gap: 10 },
  logoCircle: {
    width: 38, height: 38, borderRadius: 19,
    backgroundColor: "rgba(255,255,255,0.2)",
    alignItems: "center", justifyContent: "center",
  },
  appBarTitle: { color: "#fff", fontSize: 18, fontWeight: "700" },
  centered: { flex: 1, alignItems: "center", justifyContent: "center", padding: 24 },
  successCard: {
    borderRadius: 24, padding: 30,
    alignItems: "center", gap: 14,
    shadowColor: "#000", shadowOffset: { width: 0, height: 8 }, shadowOpacity: 0.08, shadowRadius: 24, elevation: 4,
  },
  successTitle: { fontSize: 22, fontWeight: "800" },
  successBody: { fontSize: 14, textAlign: "center", lineHeight: 21 },
  scroll: { flexGrow: 1, paddingHorizontal: 20, paddingTop: 28, paddingBottom: 60, gap: 8 },
  eyebrow: { fontSize: 11, fontWeight: "700", letterSpacing: 3, textTransform: "uppercase", marginBottom: 4 },
  title: { fontSize: 30, fontWeight: "800", marginBottom: 6 },
  copy: { fontSize: 14, lineHeight: 20, marginBottom: 20 },
  card: {
    borderRadius: 24, padding: 24, gap: 12,
    borderWidth: 1,
    shadowColor: "#000", shadowOffset: { width: 0, height: 12 }, shadowOpacity: 0.1, shadowRadius: 30, elevation: 8,
  },
  headIcon: {
    alignSelf: "flex-start",
    backgroundColor: "rgba(0,0,0,0.04)",
    borderRadius: 16, padding: 12,
  },
  fieldLabel: { fontSize: 12, fontWeight: "500", marginBottom: -4 },
  inputRow: {
    flexDirection: "row", alignItems: "center", gap: 10,
    borderRadius: 9999, borderWidth: 1,
    paddingHorizontal: 16, paddingVertical: 13,
  },
  input: { flex: 1, fontSize: 15 },
  errorBox: {
    flexDirection: "row", alignItems: "center", gap: 8,
    borderRadius: 10, padding: 10,
  },
  errorText: { fontSize: 13, flex: 1, fontWeight: "600" },
  primaryBtn: {
    borderRadius: 9999, height: 54,
    flexDirection: "row", alignItems: "center", justifyContent: "center", gap: 8,
    shadowOffset: { width: 0, height: 6 }, shadowOpacity: 0.35, shadowRadius: 14, elevation: 6,
    marginTop: 4,
  },
  primaryBtnText: { color: "#fff", fontSize: 17, fontWeight: "800" },
  secondaryBtn: {
    borderRadius: 9999, height: 48,
    alignItems: "center", justifyContent: "center",
    borderWidth: 1,
  },
  secondaryBtnText: { fontSize: 16, fontWeight: "700" },
});

import { Ionicons, MaterialIcons } from "@expo/vector-icons";
import { LinearGradient } from "expo-linear-gradient";
import { useState } from "react";
import {
  KeyboardAvoidingView,
  Platform,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  View,
  ActivityIndicator,
} from "react-native";
import { api } from "../lib/api";
import { useTheme } from "../modules/theme/ThemeContext";

type Step = "email" | "code" | "password";

export function ForgotPasswordScreen() {
  const { tokens, mode } = useTheme();
  const [step, setStep] = useState<Step>("email");
  const [email, setEmail] = useState("");
  const [verificationCode, setVerificationCode] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  const isDark = mode === "dark";

  async function handleRequestCode() {
    if (!email.trim()) { setError("Email is required"); return; }
    setError(null); setLoading(true);
    try {
      await api.requestPasswordReset(email.trim());
      setStep("code");
      setSuccessMessage("Verification code sent to your email!");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to send verification code");
    } finally { setLoading(false); }
  }

  async function handleVerifyCode() {
    if (verificationCode.length !== 6) { setError("Verification code must be 6 digits"); return; }
    setError(null); setLoading(true);
    try {
      await api.verifyResetCode(email.trim(), verificationCode);
      setStep("password");
      setSuccessMessage("Code verified! Now set your new password.");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Invalid or expired verification code");
    } finally { setLoading(false); }
  }

  async function handleResetPassword() {
    if (!newPassword) { setError("New password is required"); return; }
    if (newPassword.length < 6) { setError("Password must be at least 6 characters"); return; }
    if (newPassword !== confirmPassword) { setError("Passwords do not match"); return; }
    setError(null); setLoading(true);
    try {
      await api.resetPassword(email.trim(), verificationCode, newPassword);
      setSuccessMessage("Password reset successfully!");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to reset password");
    } finally { setLoading(false); }
  }

  return (
    <View style={[styles.root, { backgroundColor: tokens.background }]}>
      <KeyboardAvoidingView behavior={Platform.OS === "ios" ? "padding" : undefined} style={{ flex: 1 }}>
        <ScrollView contentContainerStyle={styles.scroll}>
          <LinearGradient
            colors={[isDark ? tokens.primaryContainer : "#0f766e", isDark ? "#1a3050" : "#0d5b55", isDark ? "#14161c" : "#1c2430"]}
            start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }}
            style={styles.banner}
          >
            <View style={styles.bannerIcon}>
              <Ionicons name="lock-open" size={32} color="#fff" />
            </View>
            <Text style={styles.bannerEyebrow}>Password Reset</Text>
            <Text style={styles.bannerTitle}>Recover Your Account</Text>
            <Text style={styles.bannerSubtitle}>
              Step {step === "email" ? "1" : step === "code" ? "2" : "3"} of 3
            </Text>
          </LinearGradient>

          {successMessage && (
            <View style={[styles.successCard, {
              backgroundColor: isDark ? `${tokens.secondary}15` : "#ecfdf5",
              borderColor: isDark ? tokens.secondary : "#6ee7b7",
            }]}>
              <Ionicons name="checkmark-circle" size={24} color={tokens.secondary} />
              <Text style={[styles.successText, { color: isDark ? tokens.onSecondaryContainer : "#047857" }]}>{successMessage}</Text>
            </View>
          )}

          {error && (
            <View style={[styles.errorCard, {
              backgroundColor: isDark ? `${tokens.error}18` : "#fef2f2",
              borderColor: isDark ? tokens.error : "#fca5a5",
            }]}>
              <Ionicons name="alert-circle" size={24} color={tokens.error} />
              <Text style={[styles.errorText, { color: isDark ? tokens.onErrorContainer : "#dc2626" }]}>{error}</Text>
            </View>
          )}

          <View style={[styles.formCard, {
            backgroundColor: isDark ? tokens.surfaceContainerLow : tokens.surfaceContainerLowest,
            borderColor: isDark ? tokens.outlineVariant : "rgba(0,0,0,0.06)",
          }]}>
            {step === "email" && (
              <>
                <Text style={[styles.formLabel, { color: tokens.onSurface }]}>Email Address</Text>
                <View style={[styles.inputRow, { backgroundColor: tokens.surfaceContainerLowest, borderColor: tokens.outlineVariant }]}>
                  <MaterialIcons name="email" size={20} color={tokens.outline} />
                  <TextInput
                    style={[styles.input, { color: tokens.onSurface }]}
                    placeholder="Enter your email"
                    placeholderTextColor={tokens.onSurfaceVariant}
                    value={email}
                    onChangeText={setEmail}
                    keyboardType="email-address"
                    autoCapitalize="none"
                    autoCorrect={false}
                  />
                </View>
                <Text style={[styles.hint, { color: tokens.onSurfaceVariant }]}>Enter the email associated with your account</Text>
              </>
            )}

            {step === "code" && (
              <>
                <Text style={[styles.formLabel, { color: tokens.onSurface }]}>Verification Code</Text>
                <TextInput
                  style={[styles.codeInput, {
                    backgroundColor: tokens.surfaceContainerLowest,
                    color: tokens.onSurface,
                    borderColor: tokens.outlineVariant,
                  }]}
                  placeholder="000000"
                  placeholderTextColor={tokens.onSurfaceVariant}
                  value={verificationCode}
                  onChangeText={(text) => setVerificationCode(text.replace(/\D/g, "").slice(0, 6))}
                  keyboardType="number-pad"
                  maxLength={6}
                />
                <Text style={[styles.hint, { color: tokens.onSurfaceVariant }]}>Enter the 6-digit code sent to your email (expires in 10 minutes)</Text>
              </>
            )}

            {step === "password" && (
              <>
                <Text style={[styles.formLabel, { color: tokens.onSurface }]}>New Password</Text>
                <View style={[styles.inputRow, { backgroundColor: tokens.surfaceContainerLowest, borderColor: tokens.outlineVariant }]}>
                  <MaterialIcons name="vpn-key" size={20} color={tokens.outline} />
                  <TextInput
                    style={[styles.input, { color: tokens.onSurface }]}
                    placeholder="At least 6 characters"
                    placeholderTextColor={tokens.onSurfaceVariant}
                    value={newPassword}
                    onChangeText={setNewPassword}
                    secureTextEntry={!showPassword}
                  />
                  <Pressable onPress={() => setShowPassword(!showPassword)}>
                    <MaterialIcons name={showPassword ? "visibility" : "visibility-off"} size={20} color={tokens.outline} />
                  </Pressable>
                </View>

                <Text style={[styles.formLabel, { color: tokens.onSurface }]}>Confirm Password</Text>
                <View style={[styles.inputRow, { backgroundColor: tokens.surfaceContainerLowest, borderColor: tokens.outlineVariant }]}>
                  <MaterialIcons name="vpn-key" size={20} color={tokens.outline} />
                  <TextInput
                    style={[styles.input, { color: tokens.onSurface }]}
                    placeholder="Confirm your password"
                    placeholderTextColor={tokens.onSurfaceVariant}
                    value={confirmPassword}
                    onChangeText={setConfirmPassword}
                    secureTextEntry={!showPassword}
                  />
                </View>
              </>
            )}
          </View>

          <View style={styles.buttonGroup}>
            <Pressable
              style={({ pressed }) => [styles.primaryBtn, {
                backgroundColor: tokens.secondary,
                shadowColor: isDark ? "#000" : "#006a63",
                opacity: pressed || loading ? 0.85 : 1,
              }]}
              onPress={
                step === "email"
                  ? () => void handleRequestCode()
                  : step === "code"
                    ? () => void handleVerifyCode()
                    : () => void handleResetPassword()
              }
              disabled={loading}
            >
              {loading ? (
                <ActivityIndicator color="#fff" />
              ) : (
                <Text style={styles.primaryBtnText}>
                  {step === "email" ? "Send Code" : step === "code" ? "Verify Code" : "Reset Password"}
                </Text>
              )}
            </Pressable>
          </View>
        </ScrollView>
      </KeyboardAvoidingView>
    </View>
  );
}

const styles = StyleSheet.create({
  root: { flex: 1 },
  scroll: { flexGrow: 1, paddingHorizontal: 16, paddingVertical: 20, gap: 16 },
  banner: {
    borderRadius: 24, padding: 24, gap: 10,
    shadowColor: "#000", shadowOffset: { width: 0, height: 4 }, shadowOpacity: 0.08, shadowRadius: 16, elevation: 4,
  },
  bannerIcon: {
    alignSelf: "flex-start",
    backgroundColor: "rgba(255,255,255,0.15)", borderRadius: 16, padding: 12,
  },
  bannerEyebrow: { color: "rgba(255,255,255,0.85)", letterSpacing: 1, fontSize: 11, fontWeight: "800", textTransform: "uppercase" },
  bannerTitle: { fontSize: 28, fontWeight: "900", color: "#fff", letterSpacing: -0.5 },
  bannerSubtitle: { color: "rgba(255,255,255,0.88)", fontSize: 14, fontWeight: "500" },
  successCard: {
    borderWidth: 1, borderRadius: 12, padding: 12,
    flexDirection: "row", gap: 12, alignItems: "center",
  },
  successText: { fontSize: 14, fontWeight: "500", flex: 1 },
  errorCard: {
    borderWidth: 1, borderRadius: 12, padding: 12,
    flexDirection: "row", gap: 12, alignItems: "center",
  },
  errorText: { fontSize: 14, fontWeight: "500", flex: 1 },
  formCard: {
    borderRadius: 20, padding: 20, gap: 12,
    borderWidth: 1,
  },
  formLabel: { fontSize: 14, fontWeight: "600", marginBottom: -4 },
  inputRow: {
    flexDirection: "row", alignItems: "center", gap: 10,
    borderRadius: 9999, borderWidth: 1,
    paddingHorizontal: 16, paddingVertical: 13,
  },
  input: { flex: 1, fontSize: 16 },
  codeInput: {
    borderRadius: 14, borderWidth: 1,
    paddingHorizontal: 14, paddingVertical: 18,
    fontSize: 32, letterSpacing: 12,
    textAlign: "center", fontWeight: "bold",
  },
  hint: { fontSize: 12, marginTop: -4 },
  buttonGroup: { gap: 12 },
  primaryBtn: {
    borderRadius: 16, height: 52,
    alignItems: "center", justifyContent: "center",
    shadowOffset: { width: 0, height: 4 }, shadowOpacity: 0.3, shadowRadius: 12, elevation: 5,
  },
  primaryBtnText: { color: "#fff", fontSize: 16, fontWeight: "800" },
});

