     1→import { createContext, useContext, useEffect, useState, type ReactNode } from "react";
     2→import * as SecureStore from "expo-secure-store";
     3→import { darkTokens, lightTokens, type TokenSet } from "../../theme/tokens";
     4→
     5→const THEME_KEY = "ugc_theme_mode";
     6→
     7→type ThemeMode = "light" | "dark";
     8→
     9→type ThemeContextValue = {
    10→  mode: ThemeMode;
    11→  tokens: TokenSet;
    12→  toggle: () => void;
    13→  setMode: (m: ThemeMode) => void;
    14→};
    15→
    16→const ThemeContext = createContext<ThemeContextValue | undefined>(undefined);
    17→
    18→export function ThemeProvider({ children }: { children: ReactNode }) {
    19→  const [mode, setModeState] = useState<ThemeMode>("light");
    20→  const [loaded, setLoaded] = useState(false);
    21→
    22→  useEffect(() => {
    23→    SecureStore.getItemAsync(THEME_KEY)
    24→      .then((val) => {
    25→        if (val === "dark" || val === "light") setModeState(val);
    26→      })
    27→      .catch(() => {})
    28→      .finally(() => setLoaded(true));
    29→  }, []);
    30→
    31→  const setMode = (m: ThemeMode) => {
    32→    setModeState(m);
    33→    SecureStore.setItemAsync(THEME_KEY, m).catch(() => {});
    34→  };
    35→
    36→  const toggle = () => setMode(mode === "light" ? "dark" : "light");
    37→
    38→  const tokens = mode === "dark" ? darkTokens : lightTokens;
    39→
    40→  if (!loaded) return null;
    41→
    42→  return (
    43→    <ThemeContext.Provider value={{ mode, tokens, toggle, setMode }}>
    44→      {children}
    45→    </ThemeContext.Provider>
    46→  );
    47→}
    48→
    49→export function useTheme() {
    50→  const ctx = useContext(ThemeContext);
    51→  if (!ctx) throw new Error("useTheme must be inside ThemeProvider");
    52→  return ctx;
    53→}
