     8→import lombok.RequiredArgsConstructor;
     9→import org.springframework.security.core.userdetails.UserDetails;
    10→import org.springframework.security.core.userdetails.UserDetailsService;
    11→import org.springframework.security.core.userdetails.UsernameNotFoundException;
    12→import org.springframework.stereotype.Service;
    13→
    14→@Service
    15→@RequiredArgsConstructor
    16→public class MongoUserDetailsService implements UserDetailsService {
    17→
    18→    private final UserRepository userRepository;
    19→    private final StudentRepository studentRepository;
    20→
    21→    @Override
    22→    public UserDetails loadUserByUsername(String username) throws UsernameNotFoundException {
    23→        String key = username == null ? "" : username.trim();
    24→        if (key.isEmpty()) {
    25→            throw new UsernameNotFoundException("User not found");
    26→        }
    27→
    28→        return userRepository.findByUsernameIgnoreCase(key)
    29→                .map(this::buildPrincipal)
    30→                .orElseGet(() -> studentRepository.findByStudentIdIgnoreCase(key)
    31→                        .flatMap(student -> userRepository.findById(student.getUserId())
    32→                                .map(user -> buildPrincipal(user, student)))
    33→                        .orElseGet(() -> studentRepository.findFirstByEmailIgnoreCase(key)
    34→                                .flatMap(student -> userRepository.findById(student.getUserId())
    35→                                        .map(user -> buildPrincipal(user, student)))
    36→                                .orElseThrow(() -> new UsernameNotFoundException("User not found"))));
    37→    }
    38→
    39→    private UserPrincipal buildPrincipal(User user) {
    40→        return buildPrincipal(user, null);
    41→    }
    42→
    43→    private UserPrincipal buildPrincipal(User user, Student student) {
    44→        boolean updatedCampus = false;
    45→        if (user.getCampusId() == null || user.getCampusId().isBlank()) {
    46→            if (student != null) {
    47→                String studentCampusId = student.getCampusId();
    48→                if (studentCampusId != null && !studentCampusId.isBlank()) {
    49→                    user.setCampusId(studentCampusId);
    50→                    updatedCampus = true;
    51→                }
    52→            } else if (user.getStudentId() != null && !user.getStudentId().isBlank()) {
    53→                updatedCampus = studentRepository.findByStudentIdIgnoreCase(user.getStudentId())
    54→                        .map(Student::getCampusId)
    55→                        .filter(campusId -> campusId != null && !campusId.isBlank())
    56→                        .map(campusId -> {
    57→                            user.setCampusId(campusId);
    58→                            return true;
    59→                        })
    60→                        .orElse(false);
    61→            }
    62→        }
    63→        if (updatedCampus) {
    64→            userRepository.save(user);
    65→        }
    66→        return new UserPrincipal(user);
    67→    }
    68→}
